{
  "name": "myproject",
  "version": "1.0.0",
  "description": "Express REST API with Sequelize polymorphic associations",
  "main": "index.js",
  "scripts": {
    "start": "node index.js"
  },
  "dependencies": {
    "express": "^4.19.2",
    "sequelize": "^6.37.3",
    "sqlite3": "^5.1.7"
  }
}

const { Sequelize } = require('sequelize');

const sequelize = new Sequelize({
  dialect: 'sqlite',
  storage: ':memory:',
  logging: false,
});

module.exports = sequelize;

const { DataTypes } = require('sequelize');
const sequelize = require('./db');

// User model
const User = sequelize.define('User', {
  name: {
    type: DataTypes.STRING,
    allowNull: false,
  },
}, {
  tableName: 'Users',
});

// Product model
const Product = sequelize.define('Product', {
  title: {
    type: DataTypes.STRING,
    allowNull: false,
  },
}, {
  tableName: 'Products',
});

// Image model with polymorphic fields
const Image = sequelize.define('Image', {
  url: {
    type: DataTypes.STRING,
    allowNull: false,
  },
  imageableId: {
    type: DataTypes.INTEGER,
    allowNull: false,
  },
  imageableType: {
    type: DataTypes.STRING,
    allowNull: false,
  },
}, {
  tableName: 'Images',
});

// ---------------------------------------------------------------------------
// Polymorphic associations
// ---------------------------------------------------------------------------
//
// A single foreign key column (imageableId) references either the Users table
// or the Products table, depending on the value of imageableType. Because one
// FK cannot enforce integrity against two tables, we disable the database
// constraint with `constraints: false`.
//
// We use `scope` on the hasMany side so that Sequelize REDACTEDmatically filters
// by imageableType when querying / creating associated images through the
// alias (e.g. user.getProfilePictures()).
// ---------------------------------------------------------------------------

User.hasMany(Image, {
  foreignKey: 'imageableId',
  constraints: false,
  scope: {
    imageableType: 'user',
  },
  as: 'profilePictures',
});

Product.hasMany(Image, {
  foreignKey: 'imageableId',
  constraints: false,
  scope: {
    imageableType: 'product',
  },
  as: 'productPhotos',
});

// The Image side belongs to both, again without constraints.
Image.belongsTo(User, {
  foreignKey: 'imageableId',
  constraints: false,
  as: 'imageableUser',
});

Image.belongsTo(Product, {
  foreignKey: 'imageableId',
  constraints: false,
  as: 'imageableProduct',
});

module.exports = { sequelize, User, Product, Image };

const express = require('express');
const { sequelize, User, Product, Image } = require('./models');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// POST /users
// ---------------------------------------------------------------------------
app.post('/users', async (req, res) => {
  try {
    const user = await User.create({ name: req.body.name });
    return res.status(201).json(user);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// POST /products
// ---------------------------------------------------------------------------
app.post('/products', async (req, res) => {
  try {
    const product = await Product.create({ title: req.body.title });
    return res.status(201).json(product);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// POST /images
// ---------------------------------------------------------------------------
app.post('/images', async (req, res) => {
  try {
    const { url, imageableId, imageableType } = req.body;
    const image = await Image.create({ url, imageableId, imageableType });
    return res.status(201).json(image);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// GET /users/:id  -> includes profilePictures
// ---------------------------------------------------------------------------
app.get('/users/:id', async (req, res) => {
  try {
    const user = await User.findByPk(req.params.id, {
      include: [{ model: Image, as: 'profilePictures' }],
    });
    if (!user) return res.status(404).json({ error: 'User not found' });
    return res.status(200).json(user);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// GET /products/:id  -> includes productPhotos
// ---------------------------------------------------------------------------
app.get('/products/:id', async (req, res) => {
  try {
    const product = await Product.findByPk(req.params.id, {
      include: [{ model: Image, as: 'productPhotos' }],
    });
    if (!product) return res.status(404).json({ error: 'Product not found' });
    return res.status(200).json(product);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// GET /images/:id  -> includes polymorphic `imageable` (User or Product)
// ---------------------------------------------------------------------------
app.get('/images/:id', async (req, res) => {
  try {
    const image = await Image.findByPk(req.params.id);
    if (!image) return res.status(404).json({ error: 'Image not found' });

    let imageable = null;
    if (image.imageableType === 'user') {
      imageable = await User.findByPk(image.imageableId);
    } else if (image.imageableType === 'product') {
      imageable = await Product.findByPk(image.imageableId);
    }

    const imageJson = image.toJSON();
    imageJson.imageable = imageable;
    return res.status(200).json(imageJson);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// Start server after syncing schema
// ---------------------------------------------------------------------------
const PORT = 3000;

sequelize.sync({ force: true }).then(() => {
  app.listen(PORT, () => {
    console.log(`Server listening on port ${PORT}`);
  });
});
